BACKUP=pathlib.Path('/home/appontrack/.ayo-backup-black-mic-v7-20261105')
EXPECTED=json.loads(sys.argv[1])
if not ROOT.is_dir() or ROOT.is_symlink() or ROOT.resolve()!=pathlib.Path('/home/appontrack/public_html/ayo').resolve():
 raise RuntimeError('AYO docroot mismatch')
