if not guard.is_file():raise RuntimeError('owner guard was not provisioned')
if BACKUP.exists():raise RuntimeError('existing backup path, refusing overwrite')
config=json.loads(pathlib.Path('/home/appontrack/ontrack-voice-link/config.json').read_text())
token=config['token']
headers={'Authorization':'Bearer '+token,'Accept':'application/vnd.github+json','User-Agent':'OnTrack-AYO-Pinned-Publisher'}
prepared={}
def gitblob(b):
 return hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest()
for name,sha in EXPECTED.items():
 if name not in {'index.php','app.js','style.css','api.php','secure-vault.php','ayo-mic-stt.js','voice-expression.php'}:
  raise RuntimeError('disallowed target '+name)
 url='https://api.github.com/repos/OnTrack-Development/OnTrack-voice/contents/ayo/'+name+'?ref=feat/ayo-php-host-demo-20261105'
 with urllib.request.urlopen(urllib.request.Request(url,headers=headers),timeout=10) as response:
  data=json.load(response)
 if data.get('sha')!=sha:raise RuntimeError('remote SHA mismatch '+name)
 raw=base64.b64decode(data['content'],validate=False)
 if gitblob(raw)!=sha:raise RuntimeError('blob integrity failure '+name)
 prepared[name]=raw
php=shutil.which('php') or '/usr/local/bin/php'
with tempfile.TemporaryDirectory(prefix='.ayo-release-',dir='/home/appontrack') as tmp:
 temp=pathlib.Path(tmp)
 for name,raw in prepared.items():(temp/name).write_bytes(raw)
 for name in ('api.php','index.php','secure-vault.php','voice-expression.php'):
  lint=subprocess.run([php,'-l',str(temp/name)],capture_output=True,text=True,timeout=15)
  if lint.returncode:raise RuntimeError('PHP lint failed '+name)
 BACKUP.mkdir(mode=0o700)
 existing=[]
 for name in EXPECTED:
  old=ROOT/name
  if old.is_symlink():raise RuntimeError('existing symlink '+name)
  if old.exists():
   (BACKUP/name).write_bytes(old.read_bytes())
   existing.append(name)
 updated=[]
 try:
  for name,raw in prepared.items():
   target=ROOT/name
   tempName=ROOT/(name+'.ayo-stage-v7')
   if tempName.exists():raise RuntimeError('temp collision '+name)
   fd=os.open(tempName,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o644)
   with os.fdopen(fd,'wb') as f:f.write(raw)
   os.chmod(tempName,0o644)
   os.replace(tempName,target)
   updated.append(name)
 except Exception:
  for name in updated:
   dest=ROOT/name
   if name in existing:
    dest.write_bytes((BACKUP/name).read_bytes());os.chmod(dest,0o644)
   else:dest.unlink(missing_ok=True)
  raise
 print(json.dumps({'deployed':True,'path':str(ROOT),'files':sorted(updated),'git_integrity':'pass','php_lint':'pass','private_guard':'ready','backup':'outside_docroot','assets_untouched':True}))
